    "id": 246,
    "title": "Nature：神经元受限迁移引发非致死性DNA损伤",
    "summary": "《自然》最新研究表明，发育中的大脑和小脑皮层神经元在迁移过程中，会因机械应力产生大量非致死性的DNA双链断裂。",
    "body": "近日发表于《自然》（Nature）的一项研究揭示了神经元发育过程中的新机制。研究发现，在发育中的大脑和小脑皮层里，神经元的迁移伴随着大量的DNA双链断裂。\n\n这种DNA损伤主要是由神经元在受限空间内迁移时所产生的机械应力引起的。尽管造成了DNA断裂，但这种损伤被证实是非致死性的，表明发育中的神经元具备应对此类机械压力的耐受或修复机制。\n\n这一发现加深了科学界对神经系统发育过程中细胞力学与基因组稳定性相互作用的理解，为探索神经发育及相关疾病的潜在机制提供了重要的理论基础。",
    "category": "生物医药",
    "tags": [
      "神经元发育",
      "DNA损伤",
      "神经科学",
      "Nature"
    ],
    "source": "Zhang; Zhejing; Canela; Andres; Kurisu; Junko; Zou; Peilin; Kawaue; Takumi; Nakazawa; Naotaka; Takeda; Noriko; Saeki; Mai; Utsunomiya; Masaki; Bilgic; Merve; Ishidate; Fumiyoshi; Grenci; Gianluca; Furuta; Takahiro; Kishi; Yusuke; Sasanuma; Hiroyuki; Kengaku; Mineko",
    "time": "18小时前",
